import{showInfection}from './infection-visuals.js?v=20261023-physicscomplete01';
import{infectionTasks,validInfectionAnswer}from './infection-models.js?v=20261023-physicscomplete01';
export{showInfection};
export function mountInfection(l,p,root,{save,done,feedback}){let w=p.widget,key=l.widget.slice(10),tasks=infectionTasks[key];w.task??=0;w.infectionDrafts??={};w.passed??=[];let index=w.task%tasks.length,t=tasks[index],v=w.infectionDrafts[index]??={state:0,answer:'',seen:[]};const $=s=>root.querySelector(s);root.innerHTML=`<p><b>${index+1} / ${tasks.length} · ${t.title}</b></p><label class="field-label" for="infectionState">Compare model state</label><select class="lab-select" id="infectionState">${t.states.map((s,i)=>`<option value="${i}" ${v.state===i?'selected':''}>${s[1]}</option>`).join('')}</select><label class="field-label" for="infectionPrediction">${t.prompt}</label><select class="lab-select" id="infectionPrediction"><option value="">Choose…</option>${t.choices.map((c,i)=>`<option value="${i}" ${String(v.answer)===String(i)?'selected':''}>${c}</option>`).join('')}</select><button class="secondary" id="revealInfection">Reveal comparison →</button><p id="infectionReadout" aria-live="polite"></p><p id="infectionEvidence"></p><div class="model-actions"><button class="secondary" id="recordInfection">Record reasoning</button><button class="secondary" id="nextInfection">Next challenge →</button></div><p id="infectionProgress">${w.passed.length} / ${tasks.length} complete</p>`;
const draw=()=>{let revealed=v.revealed===v.state;showInfection(t.scene,{kind:t.scene,state:t.states[v.state][0],revealed,title:t.title,stateLabel:t.states[v.state][1],result:revealed?t.results[v.state]:''});$('#infectionReadout').textContent=revealed?t.results[v.state]:'Predict before revealing the model change.';$('#infectionEvidence').textContent='Recorded comparisons: '+t.states.map((s,i)=>(v.seen.includes(i)?'✓ ':'○ ')+s[1]).join(' · ');};
$('#infectionState').onchange=e=>{v.state=Number(e.target.value);v.answer='';delete v.revealed;save();mountInfection(l,p,root,{save,done,feedback});};$('#infectionPrediction').onchange=e=>{v.answer=e.target.value;save();};$('#revealInfection').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.state;save();draw();feedback(validInfectionAnswer(t,v.state,v.answer)?'Prediction agrees with the model. Record your reasoning.':t.why,!validInfectionAnswer(t,v.state,v.answer));};$('#recordInfection').onclick=()=>{if(v.revealed!==v.state||!validInfectionAnswer(t,v.state,v.answer)){feedback(t.why+' Predict, reveal and match the evidence before recording.',true);return;}if(!v.seen.includes(v.state))v.seen.push(v.state);if(v.seen.length===t.states.length&&!w.passed.includes(index))w.passed.push(index);if(w.passed.length===tasks.length){p.widgetDone=true;done();}save();draw();$('#infectionProgress').textContent=w.passed.length+' / '+tasks.length+' complete';feedback(v.seen.length===t.states.length?'All comparisons recorded. '+t.why:'Comparison recorded. Change state to test the other case.');};$('#nextInfection').onclick=()=>{if(!w.passed.includes(index)){feedback('Record every comparison in this challenge first.',true);return;}w.task=(index+1)%tasks.length;save();feedback('');mountInfection(l,p,root,{save,done,feedback});};draw();}
